#!/usr/bin/env python3
"""Validate the chart package's emitted-spec corpus against the vendored
Vega-Lite schema.

The chart export is a hand-written typed mirror of Vega-Lite v6, and a hand
mirror drifts the way no compiler catches: a key spelled wrong, an enum
string that the schema never listed, a property moved to a channel whose
field definition does not carry it. The corpus is the machine-checkable
half of the mirror's fidelity contract:

  chart/corpus/*.json        golden specs, regenerated by
                             `MOONFRAME_VEGA_CORPUS_REFRESH=1 moon test -p ihb2032/MoonFrame/chart`
                             (the corpus test regenerates and compares on
                             every plain run, so the committed files cannot
                             fall behind the emitter)
  vega_lite_v6_5_0.schema.json   the pinned Vega-Lite 6.5.0 JSON schema
                             (draft-07), the single home of the property
                             lists the mirror transcribes

This walker implements the draft-07 subset a Vega-Lite spec actually uses —
$ref (internal), type, enum, const, pattern, items, minItems/maxItems,
minimum/maximum, properties, required, additionalProperties, anyOf/oneOf
(any-branch-pass), allOf, and not-as-skip — which is enough to reject an
unknown key, a misspelled enum string, a value of the wrong JSON kind, or a
number outside the bounds the schema draws for it (opacity 0–1 and the
like). It is deliberately not a full validator: exotic keywords are skipped
(the schema itself never writes exclusiveMinimum / exclusiveMaximum, so the
walker does not read them either), and a spec that passes here is proven
schema-shaped, not proven renderable.

Run:  python -B .github/scripts/check_vega_corpus.py            # the corpus
      python -B .github/scripts/check_vega_corpus.py --self-test  # the walker itself
"""

import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SCHEMA_PATH = os.path.join(HERE, "..", "fixtures", "vega_lite_v6_5_0.schema.json")
CORPUS_DIR = os.path.join(HERE, "..", "..", "chart", "corpus")


def load_schema():
    with open(SCHEMA_PATH, encoding="utf-8") as f:
        return json.load(f)


SCHEMA = None


def resolve(ref):
    """Follow an internal #/definitions/... pointer to its node."""
    assert ref.startswith("#/"), "only internal refs are supported: %s" % ref
    node = SCHEMA
    for part in ref[2:].split("/"):
        node = node[part]
    return node


def deref(node):
    while isinstance(node, dict) and "$ref" in node:
        node = resolve(node["$ref"])
    return node


JSON_KIND = {
    "string": str,
    "number": (int, float),
    "integer": int,
    "boolean": bool,
    "object": dict,
    "array": list,
    "null": type(None),
}


def validate(value, schema, path, errors):
    """Append (path, message) for every violated constraint we understand.

    anyOf/oneOf pass when any branch validates; branch errors are swallowed
    on success and reported only when every branch fails. That asymmetry is
    the subset's honesty: a miss here says the value fits no legal shape.
    """
    schema = deref(schema)
    if not isinstance(schema, dict):
        return

    if "const" in schema and value != schema["const"]:
        errors.append((path, "expected const %r" % (schema["const"],)))

    if "enum" in schema:
        if value not in schema["enum"]:
            errors.append(
                (path, "%r is not one of the schema's enum values" % (value,))
            )
        return

    kind = schema.get("type")
    if isinstance(kind, list):
        matched = any(fits(value, k) for k in kind)
        if not matched:
            errors.append((path, "expected one of types %s" % kind))
            return
    elif kind is not None and not fits(value, kind):
        errors.append((path, "expected type %s" % kind))
        return

    if kind == "string" or isinstance(value, str):
        pattern = schema.get("pattern")
        if pattern is not None and isinstance(value, str):
            if not re.search(pattern, value):
                errors.append((path, "%r does not match %r" % (value, pattern)))

    # Numeric bounds, applied to any number the schema says is one — an
    # integer violating `minimum: 2` is as much a violation as a float
    # outside `0..1`, and the same check applies one level down inside a
    # nested object. `bool` is not a number here even though Python says
    # otherwise.
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        limit = schema.get("minimum")
        if isinstance(limit, (int, float)) and not isinstance(limit, bool):
            if value < limit:
                errors.append((path, "%s < minimum %s" % (value, limit)))
        limit = schema.get("maximum")
        if isinstance(limit, (int, float)) and not isinstance(limit, bool):
            if value > limit:
                errors.append((path, "%s > maximum %s" % (value, limit)))

    if isinstance(value, list):
        items = schema.get("items")
        if items is not None:
            for i, element in enumerate(value):
                validate(element, items, "%s[%d]" % (path, i), errors)
        for bound, compare in (
            ("minItems", lambda n: len(value) < n),
            ("maxItems", lambda n: len(value) > n),
        ):
            if bound in schema and compare(schema[bound]):
                errors.append((path, "array length violates %s" % bound))

    if isinstance(value, dict):
        properties = schema.get("properties", {})
        required = schema.get("required", [])
        for key in required:
            if key not in value:
                errors.append((path, "missing required property %r" % key))
        additional = schema.get("additionalProperties")
        if additional is False:
            for key in value:
                if key not in properties:
                    errors.append(
                        (path, "property %r is not in the schema here" % key)
                    )
        for key, sub in value.items():
            if key in properties:
                validate(sub, properties[key], "%s.%s" % (path, key), errors)
            elif isinstance(additional, dict):
                validate(sub, additional, "%s.%s" % (path, key), errors)

    for combinator in ("anyOf", "oneOf"):
        if combinator in schema:
            for branch in schema[combinator]:
                branch_errors = []
                validate(value, branch, path, branch_errors)
                if not branch_errors:
                    break
            else:
                errors.append(
                    (path, "matches no branch of the schema's %s" % combinator)
                )

    for branch in schema.get("allOf", []):
        validate(value, branch, path, errors)


def fits(value, kind):
    python_type = JSON_KIND.get(kind)
    if python_type is None:
        return True
    if kind == "number" and isinstance(value, bool):
        return False
    return isinstance(value, python_type)


SELF_TEST_CASES = [
    # (spec, expected_ok) — a plain bar spec validates; each mutation breaks
    # exactly one constraint the walker claims to check.
    (
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "bar",
            "encoding": {"x": {"field": "a", "type": "nominal"}},
            "data": {"values": []},
        },
        True,
    ),
    (
        # unknown top-level key — additionalProperties: false on unit specs
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "bar",
            "encodings": {},
            "data": {"values": []},
        },
        False,
    ),
    (
        # enum miss: mark
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "barr",
            "data": {"values": []},
        },
        False,
    ),
    (
        # a composite mark as a bare string is legal (AnyMark unions
        # CompositeMark alongside Mark), but a misspelling is still caught
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "boxplot",
            "data": {"values": []},
        },
        True,
    ),
    (
        # enum miss on a composite mark spelling
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "boxplott",
            "data": {"values": []},
        },
        False,
    ),
    (
        # wrong JSON kind: mark as a number
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": 7,
            "data": {"values": []},
        },
        False,
    ),
    (
        # required-missing: encoding channel object without anything legal
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "bar",
            "encoding": {"x": {"fieldd": "a"}},
            "data": {"values": []},
        },
        False,
    ),
    (
        # numeric bound, float over maximum: mark opacity is 0..1
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": {"type": "bar", "opacity": 1.5},
            "data": {"values": []},
        },
        False,
    ),
    (
        # the bound itself is legal: opacity exactly 1 passes
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": {"type": "bar", "opacity": 1},
            "data": {"values": []},
        },
        True,
    ),
    (
        # numeric bound, int under minimum, nested in a transform:
        # bin.maxbins is minimum 2, and an integer violates it as surely
        # as a float would
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "bar",
            "transform": [{"bin": {"maxbins": 1}, "field": "a", "as": "a_bin"}],
            "data": {"values": []},
        },
        False,
    ),
    (
        # numeric bound one level deeper still: bandPosition inside an
        # encoding channel definition is 0..1, and a negative one is out
        {
            "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
            "mark": "bar",
            "encoding": {
                "x": {"field": "a", "type": "nominal"},
                "opacity": {"field": "a", "bandPosition": -0.5},
            },
            "data": {"values": []},
        },
        False,
    ),
]


def self_test():
    global SCHEMA
    SCHEMA = load_schema()
    failures = 0
    for i, (spec, expected_ok) in enumerate(SELF_TEST_CASES):
        errors = []
        validate(spec, SCHEMA, "$", errors)
        ok = not errors
        if ok != expected_ok:
            failures += 1
            print(
                "self-test case %d: expected %s, got %s (%s)"
                % (i, "valid" if expected_ok else "invalid", errors or "valid", spec)
            )
    if failures:
        print("vega corpus walker: %d self-test case(s) failed" % failures)
        return 1
    print("vega corpus walker: %d self-test cases pass" % len(SELF_TEST_CASES))
    return 0


def main():
    global SCHEMA
    if "--self-test" in sys.argv:
        return self_test()
    SCHEMA = load_schema()
    names = sorted(n for n in os.listdir(CORPUS_DIR) if n.endswith(".json"))
    if not names:
        print("vega corpus: no committed specs under chart/corpus/")
        return 1
    failures = 0
    for name in names:
        with open(os.path.join(CORPUS_DIR, name), encoding="utf-8") as f:
            spec = json.load(f)
        errors = []
        validate(spec, SCHEMA, "$", errors)
        if errors:
            failures += 1
            print("%s: %d schema violation(s):" % (name, len(errors)))
            for path, message in errors[:10]:
                print("  %s: %s" % (path, message))
    if failures:
        print(
            "vega corpus: %d of %d spec(s) violate the vendored schema" % (
                failures,
                len(names),
            )
        )
        return 1
    print("vega corpus: %d spec(s) match the vendored Vega-Lite 6.5.0 schema" % len(names))
    return 0


if __name__ == "__main__":
    sys.exit(main())
